"""Unit tests for the synthetic image generator's pure logic.

CI-safe (no macOS, no vision_eyes binary): exercises the generator
registry, the variant matrix, and the conservative expectation rules.
Determinism is proven via the --smoke probe: the same seeded input must
produce byte-identical images and identical manifest entries.
"""

from __future__ import annotations

import importlib.util
import json
import subprocess
import sys
from pathlib import Path

GEN = Path(__file__).resolve().parent.parent / "eval" / "gen_synthetic.py"
spec = importlib.util.spec_from_file_location("gen_synthetic", GEN)
assert spec and spec.loader
gen = importlib.util.module_from_spec(spec)
spec.loader.exec_module(gen)


def expected_for(gen_name: str, variant: str) -> dict:
    return gen.build_expected(gen_name, variant)


def test_smoke_is_deterministic() -> None:
    first = json.dumps(gen.smoke(), sort_keys=True)
    second = json.dumps(gen.smoke(), sort_keys=True)
    assert first == second


def test_smoke_matches_subprocess_output() -> None:
    proc = subprocess.run(
        [sys.executable, str(GEN), "--smoke"],
        capture_output=True,
        text=True,
        check=True,
    )
    sub = json.loads(proc.stdout)
    assert sub == gen.smoke()


def test_smoke_entry_schema() -> None:
    for eid, info in gen.smoke().items():
        assert eid.startswith("synth-")
        assert set(info) == {"sha256", "expected"}
        for key, value in info["expected"].items():
            if key == "ocr_contains":
                assert isinstance(value, list) and value
            elif key in ("ocr_empty", "humans_zero", "sports_absent"):
                assert value is True
            elif key == "rectangles_min":
                assert isinstance(value, int) and value >= 1
            else:
                raise AssertionError(f"unexpected expectation key: {key}")


def test_full_matrix_size() -> None:
    count = sum(
        1
        for g in gen.GENERATORS
        for v in gen.VARIANTS
        if not (g == "noise" and v == "noise")
    )
    assert count == 87  # 11 generators x 8 variants, minus noise/noise
    assert count + 10 == 97  # plus 10 fuzz smoke images


def test_textcard_ocr_rules() -> None:
    truth = gen.TEXT_TRUTH["textcard"]
    for variant in gen.SAFE_OCR:
        exp = expected_for("textcard", variant)
        assert exp["ocr_contains"] == truth
        assert "ocr_empty" not in exp
    for variant in ("fliph", "flipv"):
        exp = expected_for("textcard", variant)
        assert "ocr_contains" not in exp
        assert "ocr_empty" not in exp  # flips produce garbage OCR, not none
        assert exp["humans_zero"] is True
        assert exp["sports_absent"] is True


def test_geometry_rect_rules() -> None:
    for g in gen.RECT_GENS:
        for variant in gen.VARIANTS:
            exp = expected_for(g, variant)
            assert exp["rectangles_min"] == 1
            assert exp["ocr_empty"] is True
            assert exp["humans_zero"] is True
            assert exp["sports_absent"] is True


def test_plain_negative_rules() -> None:
    plain = set(gen.GENERATORS) - gen.TEXT_GENS - gen.RECT_GENS
    for g in plain:
        for variant in gen.VARIANTS:
            exp = expected_for(g, variant)
            assert set(exp) == {"ocr_empty", "humans_zero", "sports_absent"}


def test_fuzz_entries_are_smoke_tests() -> None:
    for i in range(10):
        entry = gen.fuzz_entry(i)
        assert entry["id"] == f"fuzz-{i:02d}"
        assert entry["source"] == "synthetic"
        assert entry["expected"] == {}
        assert entry["path"] == f"images/synthetic/fuzz-{i:02d}.png"

"""Tests for the bench harness scoring + extraction logic (no network)."""

import importlib.util
from pathlib import Path

import pytest

BENCH_DIR = Path(__file__).resolve().parent.parent / "bench"


@pytest.fixture(scope="module")
def harness():
    spec = importlib.util.spec_from_file_location("harness", BENCH_DIR / "harness.py")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def test_normalize(harness):
    assert harness.normalize("  14 ") == "14"
    assert harness.normalize("$1,234") == "1234"
    assert harness.normalize("  42% ") == "42"
    assert harness.normalize("Answer: 7.") == "answer: 7"


def test_extract_final_plain(harness):
    assert harness.extract_final("14") == "14"
    assert harness.extract_final("  ") == ""


def test_extract_final_reasoning_field(harness):
    cot = "I need to look at the chart.\nLet me count the bars.\nanswer: 14"
    assert harness.extract_final(cot) == "14"


def test_extract_final_last_line(harness):
    assert harness.extract_final("first line\nsecond line") == "second line"


def test_to_float(harness):
    assert harness.to_float("3.5") == 3.5
    assert harness.to_float("$12.99") == 12.99
    assert harness.to_float("about 7") == 7.0
    assert harness.to_float("n/a") is None


def test_score_chartqa_list_label(harness):
    row = {"label": ["14"], "query": "how many?"}
    assert harness.score("chartqa", row, "14") is True
    assert harness.score("chartqa", row, "15") is False
    assert harness.score("chartqa", row, " 14 ") is True


def test_score_ocrbench(harness):
    row = {"answers": ["Hello World"], "question": "what text?"}
    assert harness.score("ocrbench", row, "Hello World") is True
    assert harness.score("ocrbench", row, "hello world") is True
    assert harness.score("ocrbench", row, "Goodbye") is False


def test_score_mathvista_float(harness):
    row = {"answer": "3.5", "answer_type": "float"}
    assert harness.score("mathvista", row, "3.51") is True
    assert harness.score("mathvista", row, "3.6") is False


def test_score_mathvista_multi(harness):
    row = {"answer": "A; B", "answer_type": "multi"}
    assert harness.score("mathvista", row, "A and B") is True
    assert harness.score("mathvista", row, "A only") is False


def test_score_mathvista_free_form(harness):
    row = {"answer": "Triangle", "answer_type": "free_form"}
    assert harness.score("mathvista", row, "triangle") is True


def test_benches_registry(harness):
    assert set(harness.BENCHES) == {"chartqa", "mathvista", "ocrbench"}
    for _, meta in harness.BENCHES.items():
        assert len(meta) == 7
        assert meta[0]  # dataset
        assert meta[4]  # question field
        assert meta[5]  # answer field(s)

"""Shared fixtures: fake backends + a tiny real PNG for session tests."""

from __future__ import annotations

import base64
import io

import pytest
from PIL import Image

from deepsight.backends import ReasoningResult, SearchResult, ToolCall, VisionResult


def tiny_png_bytes(size: int = 16) -> bytes:
    buf = io.BytesIO()
    Image.new("RGB", (size, size), (120, 40, 200)).save(buf, format="PNG")
    return buf.getvalue()


def tiny_png_data_url(size: int = 16) -> str:
    return "data:image/png;base64," + base64.b64encode(tiny_png_bytes(size)).decode()


@pytest.fixture
def png_bytes() -> bytes:
    return tiny_png_bytes()


@pytest.fixture
def png_data_url() -> str:
    return tiny_png_data_url()


class FakeReasoning:
    """Scripted reasoning backend: returns canned results per call."""

    def __init__(self, script: list[ReasoningResult]) -> None:
        self.script = list(script)
        self.calls = 0
        self.last_messages: list[dict] | None = None
        self.last_tools: list[dict] | None = None
        self.last_max_tokens: int | None = None

    def chat(
        self,
        messages: list[dict],
        tools: list[dict] | None = None,
        max_tokens: int | None = None,
        response_format: dict | None = None,
    ) -> ReasoningResult:
        if self.calls >= len(self.script):
            raise AssertionError("fake reasoning script exhausted")
        self.last_messages = messages
        self.last_tools = tools
        self.last_max_tokens = max_tokens
        result = self.script[self.calls]
        self.calls += 1
        return result


@pytest.fixture
def fake_reasoning():
    def _make(script: list[ReasoningResult]) -> FakeReasoning:
        return FakeReasoning(script)

    return _make


class FakeVision:
    """Vision backend returning canned text + fixed usage."""

    def __init__(self, text: str = "answer", prompt: int = 5, completion: int = 2,
                 boxes_data: list[dict] | None = None) -> None:
        self.text = text
        self.prompt = prompt
        self.completion = completion
        self.calls = 0
        self.box_calls = 0
        self.last_prompt: str | None = None
        self.last_bytes: bytes | None = None
        self.last_max_output_tokens: int | None = None
        self.boxes_data = boxes_data if boxes_data is not None else []

    def ask(
        self, prompt: str, image_bytes: bytes, max_output_tokens: int | None = None
    ) -> VisionResult:
        self.calls += 1
        self.last_prompt = prompt
        self.last_bytes = image_bytes
        self.last_max_output_tokens = max_output_tokens
        return VisionResult(self.text, self.prompt, self.completion)

    def boxes(self, image_bytes: bytes) -> list[dict]:
        self.box_calls += 1
        self.last_bytes = image_bytes
        return list(self.boxes_data)


@pytest.fixture
def fake_vision():
    def _make(text: str = "answer", prompt: int = 5, completion: int = 2,
              boxes_data: list[dict] | None = None) -> FakeVision:
        return FakeVision(text=text, prompt=prompt, completion=completion,
                         boxes_data=boxes_data)

    return _make


def simple_result(
    content: str,
    prompt: int = 10,
    completion: int = 3,
    tool_calls: list[ToolCall] | None = None,
) -> ReasoningResult:
    return ReasoningResult(
        content=content,
        tool_calls=tool_calls or [],
        finish_reason="tool_calls" if tool_calls else "stop",
        prompt_tokens=prompt,
        completion_tokens=completion,
    )


class FakeSearchBackend:
    """Canned search backend for test."""

    def __init__(self, results: list[SearchResult] | None = None,
                 fetch_text: str | None = None) -> None:
        self.results = results or []
        self.fetch_text = fetch_text
        self.search_calls = 0
        self.fetch_calls = 0

    def search(self, query: str, count: int = 3) -> list[SearchResult]:
        self.search_calls += 1
        return self.results[:count]

    def fetch(self, url: str) -> str | None:
        self.fetch_calls += 1
        return self.fetch_text


@pytest.fixture
def fake_search():
    def _make(results: list[SearchResult] | None = None,
              fetch_text: str | None = None) -> FakeSearchBackend:
        return FakeSearchBackend(results=results, fetch_text=fetch_text)
    return _make

"""Content-addressed perception cache.

Every vision-model answer is cached by ``(image_hash, region, prompt_kind)``
so repeated looks at the same pixels never re-pay vision tokens. The cache
is the efficiency engine behind the benchmark claim: cache hits cost
nothing and keep tokens-per-correct-answer low.
"""

from __future__ import annotations

import hashlib
import time
from dataclasses import dataclass, field

_REGION_NONE = (0, 0, 0, 0)


@dataclass(slots=True)
class CacheEntry:
    """One cached vision answer with its expiry."""

    answer: str
    expires_at: float


@dataclass(slots=True)
class PerceptionCache:
    """TTL cache keyed by image hash + region + prompt kind.

    Thread-safe enough for the loop's use: lookups and stores are
    atomic dict operations under the GIL.
    """

    ttl_seconds: int = 3600
    _entries: dict[tuple[str, tuple[int, int, int, int], str], CacheEntry] = field(
        default_factory=dict
    )

    @staticmethod
    def image_hash(data: bytes) -> str:
        """SHA-256 of the raw image bytes."""
        return hashlib.sha256(data).hexdigest()

    def _key(
        self,
        image_hash: str,
        region: tuple[int, int, int, int] | None,
        kind: str,
    ) -> tuple[str, tuple[int, int, int, int], str]:
        return (image_hash, region or _REGION_NONE, kind)

    def get(
        self,
        image_hash: str,
        region: tuple[int, int, int, int] | None,
        kind: str,
    ) -> str | None:
        """Return a live cached answer or None (expired entries are dropped)."""
        key = self._key(image_hash, region, kind)
        entry = self._entries.get(key)
        if entry is None:
            return None
        if entry.expires_at < time.monotonic():
            del self._entries[key]
            return None
        return entry.answer

    def put(
        self,
        image_hash: str,
        region: tuple[int, int, int, int] | None,
        kind: str,
        answer: str,
    ) -> None:
        """Store an answer under the composite key."""
        key = self._key(image_hash, region, kind)
        self._entries[key] = CacheEntry(
            answer=answer,
            expires_at=time.monotonic() + self.ttl_seconds,
        )

    def clear(self) -> None:
        """Drop every entry (used by tests and :meth:`deepsight.doctor`)."""
        self._entries.clear()

    def __len__(self) -> int:
        return len(self._entries)

"""eval/nightly.py — nightly regression watch (eyes + reasoning loop).

Runs both evals over the manifest, compares against the previous nightly
results, and prints a compact delta report. Prints NOTHING when the
baseline is unchanged (cron watchdog pattern: empty stdout = silent).

Exit code: 0 after a normal run (even with known gaps); 1 when a runner
itself broke (missing binary/key) so the cron error alert fires.
"""

from __future__ import annotations

import json
import shutil
import subprocess
import sys
from datetime import UTC, datetime
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
EYES_DIR = ROOT / "eval" / "results"
LOOP_DIR = EYES_DIR / "loop"


def _uv_cmd() -> list[str]:
    """Locate uv (repo-managed env for run_loop_eval's deps) across common paths."""
    uv = shutil.which("uv")
    if not uv:
        for cand in (Path.home() / ".local/bin/uv", Path.home() / ".cargo/bin/uv"):
            if cand.exists():
                uv = str(cand)
                break
    if not uv:
        raise RuntimeError("uv not found; cannot run the loop eval")
    return [uv, "run", "python"]


def _latest(directory: Path) -> dict | None:
    files = sorted(directory.glob("*.json"))
    return json.loads(files[-1].read_text()) if files else None


def _summary(data: dict) -> dict:
    return {
        "checks_passed": data.get("checks_passed", 0),
        "checks_total": data.get("checks_total", 0),
        "images_ok": data.get("images_ok", 0),
        "gaps_open": data.get("gaps_open", 0),
        "skipped": data.get("skipped", 0),
        "failed": sorted(r["id"] for r in data.get("results", [])
                         if r.get("status") in ("fail", "error")),
        "gap_closed": sorted(r["id"] for r in data.get("results", [])
                             if r.get("status") == "pass" and r.get("gap")),
        "gaps": sorted(r["id"] for r in data.get("results", [])
                       if r.get("status") == "gap"),
    }


def _fmt(s: dict) -> str:
    return f"{s['images_ok']} img · {s['checks_passed']}/{s['checks_total']} chk"


def _prev(directory: Path) -> dict | None:
    latest = _latest(directory)
    return _summary(latest) if latest else None


def main() -> int:
    prev_eyes = _prev(EYES_DIR)
    prev_loop = _prev(LOOP_DIR)

    for name, cmd in (
        ("eyes", [sys.executable, "eval/run_eval.py"]),
        ("loop", [*_uv_cmd(), "eval/run_loop_eval.py"]),
    ):
        proc = subprocess.run(cmd, cwd=ROOT, capture_output=True, text=True, timeout=3600)
        if proc.returncode not in (0, 1):
            print(f"🔴 deepsight nightly: {name} runner broke (exit {proc.returncode})")
            print((proc.stdout or proc.stderr)[-800:])
            return 1

    cur_eyes = _summary(_latest(EYES_DIR) or {})
    cur_loop = _summary(_latest(LOOP_DIR) or {})

    changed = cur_eyes != prev_eyes or cur_loop != prev_loop
    if not changed:
        return 0  # silent: baseline unchanged

    lines = [f"🧠 deepsight nightly · {datetime.now(UTC).strftime('%Y-%m-%d %H:%M UTC')}"]
    eyes_line = f"eyes: {_fmt(cur_eyes)}"
    eyes_line += f" (prev {_fmt(prev_eyes)})" if prev_eyes else " (first run)"
    lines.append(eyes_line)
    loop_line = f"loop: {_fmt(cur_loop)}"
    loop_line += f" (prev {_fmt(prev_loop)})" if prev_loop else " (first run)"
    lines.append(loop_line)
    for name, cur, prev in (("eyes", cur_eyes, prev_eyes), ("loop", cur_loop, prev_loop)):
        for eid in cur["gap_closed"]:
            lines.append(f"🎉 {name}: {eid} GAP CLOSED")
        for eid in cur["failed"]:
            if not prev or eid not in prev["failed"]:
                lines.append(f"🔴 {name}: NEW FAIL {eid}")
        if prev:
            for eid in prev["failed"]:
                if eid not in cur["failed"]:
                    lines.append(f"✅ {name}: {eid} now passing")
    open_gaps = sorted(set(cur_eyes["gaps"]) | set(cur_loop["gaps"]))
    if open_gaps:
        lines.append("⚠️ open gaps: " + ", ".join(open_gaps))
    print("\n".join(lines))
    return 0


if __name__ == "__main__":
    sys.exit(main())
